/**
 * Hook de traduction. Retourne une fonction t(key) qui renvoie
 * la traduction dans la langue courante (depuis le store settings).
 */
export function useT() {
  const language = useSettingsStore((s) => s.language) as Locale;
  return useCallback(function t(key: string, params?: Record<string, string>): string {
    let text = translations[language]?.[key] ?? translations.fr[key] ?? key;
    if (params) {
      for (const [k, v] of Object.entries(params)) {
        text = text.replace(`{${k}}`, v);
      }
    }
    return text;
  }, [language]);
}

/**
 * Acces direct sans hook (pour le code non-React, ex: toast dans des callbacks).
 */
export function t(key: string, params?: Record<string, string>): string {
  const language = useSettingsStore.getState().language as Locale;
  let text = translations[language]?.[key] ?? translations.fr[key] ?? key;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      text = text.replace(`{${k}}`, v);
    }
  }
  return text;
}
